import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"What Ershu is, where it fits, and where it stops","description":"Learn how Ershu turns several repositories into project context for people and development agents.","frontmatter":{"page_id":"overview-what-is-ershu","title":"What Ershu is, where it fits, and where it stops","description":"Learn how Ershu turns several repositories into project context for people and development agents."},"headers":[],"relativePath":"en/overview/what-is-ershu.md","filePath":"en/overview/what-is-ershu.md","lastUpdated":1786290726000}'),s={name:"en/overview/what-is-ershu.md"};function i(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-ershu-is-where-it-fits-and-where-it-stops" tabindex="-1">What Ershu is, where it fits, and where it stops <a class="header-anchor" href="#what-ershu-is-where-it-fits-and-where-it-stops" aria-label="Permalink to &quot;What Ershu is, where it fits, and where it stops&quot;">​</a></h1><p>Ershu is a self-hosted code-understanding and context service. It analyzes the GitHub, GitLab, or trusted local repositories in a project as one system, builds documentation, retrieval indexes, and code relationships, then exposes the results through a web app, HTTP API, and MCP.</p><p>MCP, the Model Context Protocol, is a standard way for development agents to use external tools and data. Ershu&#39;s MCP service is a read-only query surface; it does not modify repositories.</p><h2 id="what-does-an-analysis-produce" tabindex="-1">What does an analysis produce? <a class="header-anchor" href="#what-does-an-analysis-produce" aria-label="Permalink to &quot;What does an analysis produce?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Result</th><th>Purpose</th><th>Available through</th></tr></thead><tbody><tr><td>Repository trees and file facts</td><td>Confirm paths, file types, and the analyzed revision</td><td>Web, API, MCP</td></tr><tr><td>Structured project documents</td><td>Understand modules and workflows by topic</td><td>Web, API, MCP</td></tr><tr><td>Lexical and semantic indexes</td><td>Find code by name, text, or meaning</td><td>Web, API, MCP</td></tr><tr><td>Knowledge relationships</td><td>Explore links between symbols and files</td><td>Web, API, MCP</td></tr><tr><td>Run history and checkpoints</td><td>Follow stages, usage, outcomes, and failures</td><td>Web, API</td></tr></tbody></table><p>The Worker reads analysis workspaces through restricted, read-only tools and does not execute repository scripts. Generated documentation requires an enabled model channel. Deterministic repository facts and some indexing work are separate from model-generated output.</p><h2 id="how-does-it-fit-into-daily-work" tabindex="-1">How does it fit into daily work? <a class="header-anchor" href="#how-does-it-fit-into-daily-work" aria-label="Permalink to &quot;How does it fit into daily work?&quot;">​</a></h2><ol><li>An administrator creates the first account, configures a model channel, and grants project access.</li><li>A project member adds repositories and first runs a full-project analysis across every active repository.</li><li>The Worker prepares a read-only workspace, extracts facts, and produces project-level results in the background.</li><li>People use the web app to read, search, and explore relationships. Development agents query the same project with a scoped MCP key.</li><li>Later commits can trigger incremental analysis. Cron polling and signed webhooks arrive through the API; the Worker still performs the analysis.</li></ol><p>The first run must be a full-project run. Until that baseline exists, the API rejects incremental runs so that partial output is not mistaken for a complete project view.</p><h2 id="who-is-it-for" tabindex="-1">Who is it for? <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who is it for?&quot;">​</a></h2><ul><li>Teams maintaining systems spread across several repositories;</li><li>Developers learning unfamiliar code or tracing an explanation back to its implementation;</li><li>Owners who need controlled, attributable context for development agents;</li><li>Organizations that want repository credentials, project access, and model settings to remain in their own infrastructure.</li></ul><h2 id="boundaries-to-understand-first" tabindex="-1">Boundaries to understand first <a class="header-anchor" href="#boundaries-to-understand-first" aria-label="Permalink to &quot;Boundaries to understand first&quot;">​</a></h2><ul><li>Ershu currently requires a maintainer deployment. A complete install cannot yet be assembled only from public packages because the composition and backend repositories still reference private Git sources.</li><li>Generated material helps people understand code; it does not replace source, tests, or review. Resolve conflicting statements against the current implementation.</li><li><code>/health</code> confirms that a process is alive, not that every dependency is ready. Check the database, Milvus, model channel, and Worker separately.</li><li>Creating a run through the API only queues it. No running Worker means no completed analysis.</li><li>Semantic retrieval requires working Milvus and embedding configuration. Semantic mode does not silently become lexical search; hybrid mode may report an explicit fallback.</li><li>Only administrators can configure local repositories, and each path must be in a trusted location.</li></ul><p>If these conditions fit your environment, continue to <a href="/en/configuration/">Features in context</a>. When preparing a deployment, begin with <a href="/en/configuration/basic">Basic configuration</a>.</p><blockquote><p>Sources: entry points for all five modules, repository schema, run creation and queue tests, read-only tool security tests, and the online Ershu MCP project overview.</p></blockquote>',15)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
